const i = $input.first().json || {};
let itens = [];
try { const t = typeof i.itens === 'string' && i.itens.trim() ? JSON.parse(i.itens) : (i.itens || []); itens = (Array.isArray(t) ? t : []).map((x) => ({ sku: String((x && x.sku) || '').trim(), quantidade: Math.max(1, Math.round(Number(x && x.quantidade) || 1)) })).filter((x) => x.sku).slice(0, 10); } catch (e) { itens = []; }
const lugar = String(i.cep_ou_bairro || '').trim().slice(0, 80);
const digitos = lugar.replace(/[^0-9]/g, '');
const cep8 = /^[0-9]{8}$/.test(digitos) ? digitos : '';
const valor = Number(i.valor_pedido);
const conv = String(i.conversation_id || '').trim();
return [{ json: { valido: lugar.length >= 2, cep8, conversation_id: /^[0-9a-fA-F-]{36}$/.test(conv) ? conv : '', skus: itens.map((x) => x.sku), itens, body: { p_cep_ou_bairro: lugar, p_itens: itens, p_valor_pedido: Number.isFinite(valor) && valor > 0 ? valor : null, p_pacote_arte: false } } }];

const r = $('Verificar frete no banco').first().json || {};
if (r.error || r.message || r.ok === false) return [{ json: { erro: 'indisponivel', orientacao: 'Não prometa frete nem entrega. Mantenha o atendimento, diga que já confirma o frete e peça um instante.' } }];
const S = (v) => String(v === undefined || v === null ? '' : v).replace(/bicicleta|bike|ciclista/gi, 'entrega').slice(0, 200);
const opcoes = (Array.isArray(r.opcoes) ? r.opcoes : []).slice(0, 4).map((o) => ({ descricao: S(o && (o.obs || o.texto || o.descricao)), valor_cliente: o && o.valor_cliente }));
const saida = { entrega_gratis: r.frete_gratis === true, motivo: S(r.motivo), opcoes, pedido_minimo_frete_gratis: r.pedido_minimo };
if (r.falta_para_frete_gratis > 0) saida.falta_para_frete_gratis = r.falta_para_frete_gratis;
let nac = null;
try { if ($('Cotar envio nacional').isExecuted) nac = $('Cotar envio nacional').first().json; } catch (e) { nac = null; }
const prep = $('Preparar consulta').first().json;
const cepFora = r.regiao_central === false && !!prep.cep8;
if (cepFora) {
  const semProduto = !(prep.itens && prep.itens.length);
  saida.opcoes = [{ descricao: 'retirada grátis no centro de BH', valor_cliente: 0 }];
  const ok = nac && nac.ok === true && nac.envio && nac.envio.disponivel === true && Array.isArray(nac.envio.opcoes) && nac.envio.opcoes.length > 0;
  const cidade = nac && nac.endereco && nac.endereco.cidade ? S(nac.endereco.cidade) + '/' + S(nac.endereco.uf) : '';
  if (cidade) saida.cidade_do_cep = cidade;
  if (ok) {
    saida.envio_nacional = nac.envio.opcoes.slice(0, 3).map((o) => ({ servico: S(o.servico).toLowerCase(), nome: S(o.nome), valor_frete: o.valor, prazo_dias_uteis_de_transporte: o.prazo_dias }));
    if (semProduto) saida.estimativa = true;
    saida.orientacao = 'A gráfica ENVIA PARA TODO O BRASIL pelos Correios (nunca diga que não envia). Confirme com o cliente a cidade do CEP (' + (cidade || 'informada') + ') e, se você corrigiu algum número do CEP, pergunte se é esse mesmo. Apresente PAC e SEDEX com valor e prazo de transporte (a produção vem antes) e pergunte qual ele prefere.' + (semProduto ? ' Os valores são uma ESTIMATIVA para um pacote pequeno (ainda não há produto definido): diga que o valor final sai com o produto escolhido e chame esta ferramenta de novo com os itens antes de orçar.' : ' Depois da escolha, chame montar_orcamento com o mesmo CEP e frete_servico igual a pac ou sedex nas opcoes: o frete é somado ao valor final do orçamento, do PDF e do link de pagamento. Se o pedido mudar de itens, chame esta ferramenta de novo antes de orçar.') + ' Nunca fale em Uber para fora de BH.';
  } else {
    saida.orientacao = 'A gráfica ENVIA PARA TODO O BRASIL pelos Correios (nunca diga que não envia). O valor exato sai pelo CEP e pelo produto: confirme a cidade do CEP' + (cidade ? ' (' + cidade + ')' : '') + ' e o produto, e diga que o frete é somado ao valor final. Não invente valor.';
  }
} else if (r.frete_gratis !== true) {
  saida.orientacao = 'Frete por conta do cliente (Uber Entrega) quando fora da região central ou pedido grande, ou falta chegar ao pedido mínimo. A retirada é grátis no centro de BH: ofereça sem informar o endereço (só depois do pagamento).';
}
return [{ json: saida }];
